def parse_csv_line(line):
    """Splits one line of CSV text into a list of field strings."""
    if not line:
        return [""]

    fields = []
    current_field = []
    in_quotes = False
    i = 0
    n = len(line)

    while i < n:
        char = line[i]

        if in_quotes:
            if char == '"':
                # Check for escaped quote ("")
                if i + 1 < n and line[i + 1] == '"':
                    current_field.append('"')
                    i += 2
                else:
                    in_quotes = False
                    i += 1
            else:
                current_field.append(char)
                i += 1
        else:
            if char == '"':
                in_quotes = True
                i += 1
            elif char == ',':
                fields.append("".join(current_field))
                current_field = []
                i += 1
            else:
                current_field.append(char)
                i += 1

    if in_quotes:
        raise ValueError("Unclosed quoted field")

    fields.append("".join(current_field))
    return fields
