def flatten_dict(d, sep="."):
    """Flattens a nested dictionary into a single-level dictionary.

    Only dictionaries are descended into; lists and other values are kept as they are.
    An empty nested dictionary is kept as an empty dictionary under its key.
    The input dictionary is not modified.
    """
    result = {}

    def _flatten(current, prefix=""):
        if not isinstance(current, dict):
            return

        if not current and prefix:
            result[prefix] = {}
            return

        for k, v in current.items():
            new_key = f"{prefix}{sep}{k}" if prefix else k
            if isinstance(v, dict):
                if not v:
                    result[new_key] = {}
                else:
                    _flatten(v, new_key)
            else:
                result[new_key] = v

    _flatten(d)
    return result
